def gbn_sender(frames, W):  # Go-Back-N 송신 측
    base = next_seq = 0  # base: 가장 오래된 미확인
    while base < len(frames):
        # 윈도 안이면 ACK 없이 연속 송신
        while next_seq < min(base + W, len(frames)):
            send(next_seq, frames[next_seq])
            if next_seq == base:
                start_timer()
            next_seq += 1
        ev = wait_event()  # 누적 ACK 또는 타임아웃
        if ev.kind == 'ack' and ev.num >= base:
            base = ev.num + 1  # 윈도 슬라이드
            if base < next_seq:
                start_timer()
        elif ev.kind == 'timeout':
            next_seq = base  # base부터 다시 송신
